CREATE TABLE IF NOT EXISTS gambit_migrations(version INTEGER PRIMARY KEY, applied REAL NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), data TEXT NOT NULL DEFAULT '{}', email TEXT UNIQUE COLLATE NOCASE, email_verified INTEGER NOT NULL DEFAULT 0, creator INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS content(id TEXT PRIMARY KEY, kind TEXT NOT NULL, owner TEXT REFERENCES users(id), parent TEXT REFERENCES content(id), title TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL, created REAL NOT NULL, updated REAL NOT NULL);
CREATE INDEX IF NOT EXISTS content_kind ON content(kind,status,created DESC);
CREATE INDEX IF NOT EXISTS content_parent ON content(parent,kind,created);
CREATE TABLE IF NOT EXISTS memberships(content_id TEXT REFERENCES content(id), user_id TEXT REFERENCES users(id), role TEXT NOT NULL, state TEXT NOT NULL, created REAL NOT NULL, PRIMARY KEY(content_id,user_id));
CREATE INDEX IF NOT EXISTS membership_user ON memberships(user_id,state,content_id);
CREATE TABLE IF NOT EXISTS progress(content_id TEXT REFERENCES content(id),user_id TEXT REFERENCES users(id),data TEXT NOT NULL,updated REAL NOT NULL,PRIMARY KEY(content_id,user_id));
CREATE TABLE IF NOT EXISTS platform_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,channel TEXT NOT NULL,scope TEXT NOT NULL,author TEXT REFERENCES users(id),body TEXT NOT NULL,created REAL NOT NULL,deleted INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS message_scope ON platform_messages(channel,scope,id);
CREATE TABLE IF NOT EXISTS message_reads(user_id TEXT REFERENCES users(id),channel TEXT,scope TEXT,last_id INTEGER NOT NULL,PRIMARY KEY(user_id,channel,scope));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT REFERENCES users(id),kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,link TEXT NOT NULL,created REAL NOT NULL,read_at REAL);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,id DESC);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,reporter TEXT REFERENCES users(id),kind TEXT NOT NULL,target TEXT NOT NULL,reason TEXT NOT NULL,evidence TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',notes TEXT NOT NULL DEFAULT '',created REAL NOT NULL,updated REAL NOT NULL);
CREATE INDEX IF NOT EXISTS report_status ON reports(status,created DESC);
CREATE TABLE IF NOT EXISTS content_votes(content_id TEXT REFERENCES content(id),user_id TEXT REFERENCES users(id),value INTEGER NOT NULL CHECK(value IN(-1,1)),PRIMARY KEY(content_id,user_id));
CREATE TABLE IF NOT EXISTS puzzle_ratings(user_id TEXT PRIMARY KEY REFERENCES users(id),rating INTEGER NOT NULL DEFAULT 1200,games INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS puzzle_attempts(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),puzzle_id TEXT REFERENCES content(id),data TEXT NOT NULL,started REAL NOT NULL,finished REAL);
CREATE INDEX IF NOT EXISTS puzzle_user ON puzzle_attempts(user_id,started DESC);
CREATE INDEX IF NOT EXISTS puzzle_scope ON puzzle_attempts(user_id,puzzle_id,json_extract(data,'$.session'),json_extract(data,'$.tournament'));
CREATE INDEX IF NOT EXISTS message_author_time ON platform_messages(author,created);
CREATE INDEX IF NOT EXISTS content_owner ON content(owner,kind,status);
CREATE TABLE IF NOT EXISTS puzzle_results(user_id TEXT REFERENCES users(id),puzzle_id TEXT REFERENCES content(id),attempt_id TEXT UNIQUE REFERENCES puzzle_attempts(id),delta INTEGER NOT NULL,rating_after INTEGER NOT NULL,PRIMARY KEY(user_id,puzzle_id));
CREATE TABLE IF NOT EXISTS tournament_pairings(tournament_id TEXT REFERENCES content(id),round INTEGER NOT NULL,board INTEGER NOT NULL,white TEXT REFERENCES users(id),black TEXT REFERENCES users(id),game_id TEXT UNIQUE REFERENCES games(id),result TEXT NOT NULL DEFAULT '*',PRIMARY KEY(tournament_id,round,board));
CREATE TABLE IF NOT EXISTS site_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated REAL NOT NULL);
CREATE TABLE IF NOT EXISTS email_actions(token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),kind TEXT NOT NULL,expires REAL NOT NULL,used REAL);
CREATE TABLE IF NOT EXISTS sanctions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),actor TEXT REFERENCES users(id),kind TEXT NOT NULL,reason TEXT NOT NULL,expires REAL,created REAL NOT NULL,revoked REAL);
CREATE INDEX IF NOT EXISTS sanction_user ON sanctions(user_id,kind,revoked,expires);
INSERT OR IGNORE INTO gambit_migrations VALUES(1,strftime('%s','now'));
